import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';

test('overdueInvoices returns empty array for no invoices', () => {
  const result = overdueInvoices([], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no invoices are overdue', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET30',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoice overdue by one day', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-16');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoice.number);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices excludes invoice due today', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoice due tomorrow', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const result = overdueInvoices([invoice], '2026-10-14');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const draftInv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'STICKER', qty: 5 }],
    terms: 'NET14',
  }).value;

  const result = overdueInvoices([draftInv], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued and partially_paid invoices', () => {
  const issuedInv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const tmpInv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-02',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [issuedInv.number],
  ).value;

  const partiallyPaidInv = recordPayment(
    tmpInv2,
    { amount: 100, date: '2026-09-03' },
  ).value;

  const result = overdueInvoices([issuedInv, partiallyPaidInv], '2026-10-15');
  assert.equal(result.length, 2);
  assert.equal(result[0].number, issuedInv.number);
  assert.equal(result[1].number, partiallyPaidInv.number);
});

test('overdueInvoices sorts by daysOverdue most overdue first', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [],
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-09-20',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [inv1.number],
  ).value;

  const inv3 = issueInvoice(
    createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-01',
      lines: [{ sku: 'STICKER', qty: 5 }],
      terms: 'NET14',
    }).value,
    [inv1.number, inv2.number],
  ).value;

  const result = overdueInvoices([inv1, inv2, inv3], '2026-10-16');
  assert.equal(result.length, 3);
  assert.equal(result[0].daysOverdue, 31);
  assert.equal(result[1].daysOverdue, 12);
  assert.equal(result[2].daysOverdue, 1);
});

test('overdueInvoices calculates correct daysOverdue', () => {
  const invoice = issueInvoice(
